// screens/ProfileScreen.js
import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  Image,
  Alert,
} from 'react-native';
import { MaterialIcons } from '@expo/vector-icons';
import { Fonts } from '../config/fonts';
import { useLanguage } from '../context/LanguageContext';

export default function ProfileScreen({ navigation }) {
  const { t, currentLanguage, changeLanguage, isHindi } = useLanguage();
  const [loginModalVisible, setLoginModalVisible] = useState(false);

  const menuItems = [
    { icon: 'person', label: t('profile.myProfile') || 'My Profile', color: '#FF7722' },
    { icon: 'receipt', label: t('profile.myOrders') || 'My Orders', color: '#10b981' },
    { icon: 'favorite', label: t('profile.myDonations') || 'My Donations', color: '#ef4444' },
    { icon: 'event', label: t('profile.myEvents') || 'My Events', color: '#FF7722' },
    { icon: 'card-membership', label: t('profile.idCard') || 'ID Card', color: '#f59e0b' },
    { icon: 'verified', label: t('profile.certificate') || 'Certificate', color: '#06b6d4' },
    { icon: 'notifications', label: t('profile.notifications') || 'Notifications', color: '#ec4899' },
    { icon: 'settings', label: t('profile.settings') || 'Settings', color: '#6b7280' },
  ];

  const handleMenuItemPress = (item) => {
    Alert.alert(
      t('profile.loginRequired') || 'Login Required',
      `${t('profile.pleaseLogin') || 'Please login to access'} ${item.label}`,
      [
        { text: t('common.cancel') || 'Cancel', style: 'cancel' },
        { text: t('auth.login') || 'Login', onPress: () => navigation.navigate('Login') }
      ]
    );
  };

  const handleLogin = () => {
    navigation.navigate('Login');
  };

  const handleRegister = () => {
    navigation.navigate('Register');
  };

  const handleLanguageSelect = async (lang) => {
    if (lang !== currentLanguage) {
      await changeLanguage(lang);
    }
  };

  return (
    <View style={styles.container}>
      <ScrollView showsVerticalScrollIndicator={false}>
        {/* Saffron Header */}
        <View style={styles.header}>
          <View style={styles.headerContent}>
            <View style={styles.avatarContainer}>
  <View style={styles.avatarPlaceholder}>
    <Image 
      source={{ uri: 'data:image/jpeg;base64,' }} 
      style={styles.avatarImage}
      resizeMode="cover"
    />
  </View>
</View>
            <Text style={styles.greeting}>Saheb Bandagi!</Text>

          </View>
        </View>

        {/* Login/Register Buttons - Saffron Theme */}
        <View style={styles.authButtonsContainer}>
          <TouchableOpacity style={styles.loginButton} onPress={handleLogin} activeOpacity={0.8}>
            <MaterialIcons name="login" size={24} color="#ffffff" />
            <Text style={styles.loginButtonText}>{t('auth.login') || 'Login'}</Text>
          </TouchableOpacity>
          
          <TouchableOpacity style={styles.registerButton} onPress={handleRegister} activeOpacity={0.8}>
            <MaterialIcons name="person-add" size={24} color="#FF7722" />
            <Text style={styles.registerButtonText}>{t('auth.register') || 'Register'}</Text>
          </TouchableOpacity>
        </View>

        

        {/* Footer */}
        <View style={styles.footer}>
          <Text style={styles.footerText}>
            © {new Date().getFullYear()} {t('profile.ngoManagement') || 'NGO Management'}. {t('profile.allRightsReserved') || 'All rights reserved.'}
          </Text>
        </View>
      </ScrollView>
    </View>
  );
}

